# 1.4.17 Level 60: layer box, 60 boxes, Now card, gathering only after your own gathering cast, S3 60 fields, Watch
exec(open("sim_v09.py").read().split("# reaksjon-linje")[0])
LA, GA, nsA = A; LB, GB, nsB = B
run(3)
def ev(L, s): return L.eval(s)
# layer box (not 60 needed)
print("layer box:", ev(LA, '(function() local v, s = ADDON_NS.LayerHop:TileState() return tostring(v) .. " / " .. tostring(s) end)()'))
LA.execute('ADDON_NS.LayerHop.CountMove()')
print("after a move:", ev(LA, '(function() local v, s = ADDON_NS.LayerHop:TileState() return tostring(v) .. " / " .. tostring(s) end)()'))
# gathering: ore from a quest does not count; after a Mining cast it does
LA.execute('C_Item = C_Item or {}; C_Item.GetItemInfoInstant = function(id) return id, nil, nil, nil, nil, 7, 7 end')
LA.execute('FIRE("CHAT_MSG_LOOT", "You receive loot: |cffffffff|Hitem:2771::::::::60:::::|h[Tin Ore]|h|r.")')
print("quest ore counted:", ev(LA, 'ADDON_NS.Pulse.sess.gather and ADDON_NS.Pulse.sess.gather.n or 0'))
LA.execute('FIRE("UNIT_SPELLCAST_SUCCEEDED", "player", "x", 2575)')
LA.execute('FIRE("CHAT_MSG_LOOT", "You receive loot: |cffffffff|Hitem:2771::::::::60:::::|h[Tin Ore]|h|rx2.")')
print("mined ore counted:", ev(LA, 'ADDON_NS.Pulse.sess.gather and ADDON_NS.Pulse.sess.gather.n or 0'))
# level 60
LA.execute('UnitLevel = function() return 60 end; UnitPVPRank = function() return 8 end; GetPVPRankInfo = function(r) return "Grunt", 3 end; GetPVPRankProgress = function() return 0.42 end; GetPVPSessionStats = function() return 12, 340 end')
LA.execute('local c = ADDON_NS.Tracker:MyChar(); c.level = 60; FIRE("PLAYER_LEVEL_UP", 60)'); run(4)
print("boxes at 60:", ev(LA, 'table.concat(ADDON_NS.Tiles:List(), ",")'))
LA.execute('FIRE("CHAT_MSG_COMBAT_FACTION_CHANGE", "Your Thunder Bluff reputation has increased by 75.")')
LA.execute('FIRE("CHAT_MSG_COMBAT_FACTION_CHANGE", "Your Orgrimmar reputation has increased by 25.")')
LA.execute('ADDON_NS.Pulse.sess.start = ADDON_NS.Now() - 1800')
LA.execute("local m0 = GetMoney(); GetMoney = function() return m0 + 50000 end; FIRE(\"PLAYER_MONEY\")")
LA.execute("GetMoney = function() return 10000 end; FIRE(\"PLAYER_MONEY\")")
print("gold/h never negative:", ev(LA, 'ADDON_NS.Pulse:GoldPerHour()'))
print("bosses before:", ev(LA, 'ADDON_NS.Pulse.PvEDay().bosses'))
LA.execute('FIRE("ENCOUNTER_END", 1, "Boss", 1, 5, 1)')
print("bosses after:", ev(LA, 'ADDON_NS.Pulse.PvEDay().bosses'))
LA.execute('FIRE("CHAT_MSG_LOOT", "You receive loot: |cff0070dd|Hitem:13340::::::::60:::::|h[Cape]|h|r.")')
LA.execute('ADDON_NS.Tiles:Layout(); ADDON_NS.Tiles:Update(); ADDON_NS.NowCard:Update()')
print("tile values:", ev(LA, '(function() local t = {} for _, x in ipairs(ADDON_NS.Tiles.tiles) do if x:IsShown() then t[#t+1] = tostring(x.v:GetText()) .. "/" .. tostring(x.k:GetText()) end end return table.concat(t, " | ") end)()'))
print("now big:", ev(LA, 'ADDON_NS.NowCard.frame.big:GetText() .. " " .. ADDON_NS.NowCard.frame.bigSub:GetText() .. " | " .. ADDON_NS.NowCard.frame.right:GetText()'))
print("now row:", ev(LA, 'ADDON_NS.NowCard.frame.lines[1]:GetText()'))
print("ETA at 60:", ev(LA, 'tostring(ADDON_NS.St:ETA(ADDON_NS:GetPerson(ADDON_NS.pid)))'))
# S3 to B, then B's Watch facts for A
LA.execute('ADDON_NS.Comm:Broadcast(ADDON_NS.Tracker:BuildS3(), 3)'); run(4)
print("B sees:", ev(LB, '(function() local p = ADDON_NS:GetPerson("' + LA.eval('ADDON_NS.pid') + '") local s = p and p.s3 or {} return tostring(s.rank) .. " " .. tostring(s.rankProg) .. " hk " .. tostring(s.hkT) .. " runs " .. tostring(s.runsT) .. " best " .. tostring(s.best) end)()'))
print("FEIL:", [e for e in list(GA.ERRORS.values()) if 'HookScript' not in str(e)][:5], [e for e in list(GB.ERRORS.values()) if 'HookScript' not in str(e)][:4])
print("A S3:", ev(LA, '(function() local d = ADDON_NS.Tracker:S3Data() return tostring(d.rank) .. " " .. tostring(d.rankProg) .. " " .. tostring(d.hkT) .. " " .. tostring(d.best) end)()'))
print("A msg:", ev(LA, 'ADDON_NS.Tracker:BuildS3()'))
run(70)
print("B sees later:", ev(LB, '(function() local p = ADDON_NS:GetPerson("' + LA.eval('ADDON_NS.pid') + '") local s = p and p.s3 or {} return tostring(s.rank) .. " " .. tostring(s.rankProg) .. " hk " .. tostring(s.hkT) .. " runs " .. tostring(s.runsT) .. " best " .. tostring(s.best) end)()'))
LB.execute('local p = ADDON_NS:GetPerson("' + LA.eval('ADDON_NS.pid') + '"); local c = ADDON_NS:PersonChar(p); if c then c.level = 60 end; ADDON_NS.db.watch = ADDON_NS.db.watch or {}; if not ADDON_NS.Watch:Has(p.pid) then ADDON_NS.Watch:Toggle(p.pid) end; if ADDON_NS.Watch.Create then pcall(ADDON_NS.Watch.Create, ADDON_NS.Watch) end; WF = {} for i = 1, 8 do ADDON_NS.Watch.tick = i; ADDON_NS.Watch:Update(); local r = ADDON_NS.Watch.frame and ADDON_NS.Watch.frame.rows[1]; WF[#WF+1] = r and tostring(r.fact:GetText()) or "-" end')
print("B watch facts:", ev(LB, "table.concat(WF, \" | \")"))
print("FEIL2:", [e for e in list(GA.ERRORS.values()) if 'HookScript' not in str(e)][:5], [e for e in list(GB.ERRORS.values()) if 'HookScript' not in str(e)][:4])
